#!/usr/bin/env bash
# Regenerates the checked-in binding sources from crates/firemq-client-ffi:
#
#   kotlin/src/main/kotlin/io/github/firemq/firemq_client_ffi.kt   (UniFFI)
#   swift/Sources/FireMQ/FireMQ.swift, swift/Sources/FireMQFFI/     (UniFFI)
#   ruby/lib/firemq/firemq_client_ffi.rb                           (UniFFI)
#   c/firemq.h                                                     (cbindgen)
#
# Python's UniFFI module is generated by maturin at build time. Run this after changing the
# FFI crate; CI fails when the checked-in files are stale.
#
#   bindings/generate.sh            # needs cbindgen: cargo install cbindgen --locked
set -euo pipefail

root="$(cd "$(dirname "$0")/.." && pwd)"
bindings="$root/bindings"
crate="$root/crates/firemq-client-ffi"
target="${CARGO_TARGET_DIR:-$root/target}"
cd "$root"

cargo build -p firemq-client-ffi
cargo build -p firemq-client-ffi --features cli --bin uniffi-bindgen

case "$(uname -s)" in
  Darwin) lib="$target/debug/libfiremq_client_ffi.dylib" ;;
  MINGW* | MSYS* | CYGWIN*) lib="$target/debug/firemq_client_ffi.dll" ;;
  *) lib="$target/debug/libfiremq_client_ffi.so" ;;
esac

out="$(mktemp -d)"
trap 'rm -rf "$out"' EXIT
for lang in kotlin swift ruby; do
  "$target/debug/uniffi-bindgen" generate --library "$lib" --language "$lang" \
    --out-dir "$out/$lang" --no-format > /dev/null
done

cp "$out/kotlin/io/github/firemq/firemq_client_ffi.kt" \
  "$bindings/kotlin/src/main/kotlin/io/github/firemq/firemq_client_ffi.kt"
cp "$out/swift/FireMQ.swift" "$bindings/swift/Sources/FireMQ/FireMQ.swift"
cp "$out/swift/FireMQFFI.h" "$bindings/swift/Sources/FireMQFFI/FireMQFFI.h"
cp "$out/ruby/firemq_client_ffi.rb" "$bindings/ruby/lib/firemq/firemq_client_ffi.rb"

(cd "$crate" && cbindgen --quiet --config cbindgen.toml --output "$bindings/c/firemq.h")

echo "bindings regenerated"
